// Determine whether the session is in the past (already ended or attended-like status).
// Past sessions bypass the capacity guard -- the class already happened, so swapping the
// teacher on record is a bookkeeping correction, not a scheduling conflict.
$sessionStatus = strtolower(trim((string) ($session->Status ?? 'scheduled')));
$isPastSession = in_array($sessionStatus, ['attended', 'completed', 'late', 'absent'], true);
if (!$isPastSession) {
    try {
        $sessionEndDt = Carbon::parse($sessionDate . ' ' . ($endTime ?: '23:59'));
        $isPastSession = $sessionEndDt->lte(Carbon::now());
    } catch (\Throwable $e) {
        $isPastSession = false;
    }
}

if (!$isPastSession) {
    $guard = app(ScheduleGuardService::class);
    $conflicts = $guard->validateScheduleOccurrence([
        'teacher_id' => $newTeacherId,
        'class_type' => $classType,
        'room_id' => $roomId,
        'branch_id' => $campusId,
        'schedule_date' => $sessionDate,
        'start_time' => $startTime,
        'end_time' => $endTime,
        'exclude_schedule_id' => $existingScheduled ? (int) $existingScheduled->id : null,
    ]);
    if (!empty($conflicts)) {
        $conflictMessage = $conflicts[0]['message'] ?? '代課老師此時段與既有課程衝突';
        $overlapSummary = $conflicts[0]['overlap_summary'] ?? '';
        if ($overlapSummary !== '') {
            $conflictMessage .= '（' . $overlapSummary . '）';
        }

        Log::info('[substitute] capacity_conflict', [
            'class_session_id' => $id,
            'new_teacher_id' => $newTeacherId,
            'session_date' => $sessionDate,
            'conflicts' => $conflicts,
        ]);

        return response()->json([
            'message' => $conflictMessage,
            'conflicts' => $conflicts,
        ], 409);
    }
} else {
    $this->logSubstituteDiag('guard_bypassed_past_session', [
        'class_session_id' => $id,
        'session_status' => $sessionStatus,
        'session_date' => $sessionDate,
        'new_teacher_id' => $newTeacherId,
    ]);
}

/** 歷史堂次（已上）即使代課老師同時段有既有一對一占用，仍應可代課（bypass guard）。 */
public function test_substitute_allows_past_session_even_when_capacity_would_conflict(): void
{
    Carbon::setTestNow('2026-04-15 12:00:00');
    try {
        [$dirToken, $regularTeacherId, $subTeacherId, $scId] = $this->seedCapacityConflictScenario();

        $pastSession = ClassSession::create([
            'StudentClassID' => $scId,
            'SessionDate' => '2026-04-12',
            'StartTime' => '16:30',
            'EndTime' => '18:30',
            'Status' => 'attended',
        ]);

        $res = $this->withHeaders([
            'Authorization' => "Bearer {$dirToken}",
            'Accept' => 'application/json',
        ])->postJson("/api/v1/class-sessions/{$pastSession->id}/substitute", [
            'substitute_teacher_id' => $subTeacherId,
            'reason' => '歷史堂次換代課',
        ]);

        $res->assertOk()
            ->assertJsonFragment(['substitute_teacher_id' => $subTeacherId]);
    } finally {
        Carbon::setTestNow();
    }
}

/** 未來堂次遇到容量衝突時，仍應被擋（409），且回傳含 conflicts 明細。 */
public function test_substitute_future_session_still_blocked_on_capacity_conflict(): void
{
    Carbon::setTestNow('2026-04-15 12:00:00');
    try {
        [$dirToken, $regularTeacherId, $subTeacherId, $scId] = $this->seedCapacityConflictScenario();

        $futureSession = ClassSession::create([
